-- Habilitar extensão UUID (já ativa no Supabase por padrão)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ── DROP (caso queira recriar do zero) ──────────────────────
DROP TABLE IF EXISTS standard_equipment_items CASCADE;
DROP TABLE IF EXISTS roller_tables CASCADE;
DROP TABLE IF EXISTS relationship_equip_accessory CASCADE;
DROP TABLE IF EXISTS non_combinable_comps CASCADE;
DROP TABLE IF EXISTS general_alerts CASCADE;
DROP TABLE IF EXISTS equipments CASCADE;
DROP TABLE IF EXISTS dependant_items CASCADE;
DROP TABLE IF EXISTS accessory_groups CASCADE;
DROP TABLE IF EXISTS accessories CASCADE;

-- ── CREATE TABLES ───────────────────────────────────────────

CREATE TABLE IF NOT EXISTS accessories (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  protheus_code           VARCHAR NOT NULL UNIQUE,
  legacy_group_id         INTEGER,
  color                   VARCHAR,
  predominant_material    VARCHAR,
  dimensional_mm          INTEGER,
  monitor_size            DECIMAL(5,2),
  quantity_monitor_totem  INTEGER,
  name                    VARCHAR NOT NULL,
  cost_std                DECIMAL(10,2) NOT NULL DEFAULT 0,
  description             TEXT,
  legacy_general_alert_id INTEGER DEFAULT 0,
  status                  VARCHAR NOT NULL DEFAULT 'active',
  created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS accessory_groups (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_id   INTEGER NOT NULL UNIQUE,
  name        VARCHAR NOT NULL UNIQUE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS dependant_items (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_equipment_id  INTEGER NOT NULL,
  protheus_code        VARCHAR NOT NULL,
  protheus_item_code   VARCHAR NOT NULL,
  quantity             INTEGER NOT NULL DEFAULT 1,
  cost_std             DECIMAL(10,2) NOT NULL DEFAULT 0,
  proportional_factor  DECIMAL(10,4),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS equipments (
  id                         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_id                  INTEGER NOT NULL UNIQUE,
  name                       VARCHAR NOT NULL UNIQUE,
  commercial_name            VARCHAR NOT NULL UNIQUE,
  ipi_tax_rate               DECIMAL(10,4) NOT NULL DEFAULT 0,
  contribution_margin_ratio  DECIMAL(10,4) NOT NULL DEFAULT 0,
  seller_commission          DECIMAL(10,4) NOT NULL DEFAULT 0,
  manager_commission         DECIMAL(10,4) NOT NULL DEFAULT 0,
  director_commission        DECIMAL(10,4) NOT NULL DEFAULT 0,
  certification_cost         DECIMAL(10,2) NOT NULL DEFAULT 0,
  labor_cost_rate            DECIMAL(10,4) NOT NULL DEFAULT 0,
  warranty_rate              DECIMAL(10,4) NOT NULL DEFAULT 0,
  parts_provision_rate       DECIMAL(10,4) NOT NULL DEFAULT 0,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS general_alerts (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_id   INTEGER NOT NULL UNIQUE,
  description TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS non_combinable_comps (
  id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_equipment_id   INTEGER NOT NULL,
  legacy_group_id       INTEGER NOT NULL,
  protheus_code         VARCHAR NOT NULL,
  legacy_second_group_id INTEGER,
  remove_list_code      VARCHAR NOT NULL,
  status                VARCHAR NOT NULL DEFAULT 'active',
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS relationship_equip_accessory (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_equipment_id     INTEGER NOT NULL,
  protheus_code           VARCHAR NOT NULL,
  description             TEXT,
  legacy_general_alert_id INTEGER DEFAULT 0,
  operation_time          INTEGER,
  status                  VARCHAR NOT NULL DEFAULT 'active',
  maximum_quantity        INTEGER,
  created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS roller_tables (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_equipment_id  INTEGER NOT NULL,
  protheus_code        VARCHAR NOT NULL,
  type                 VARCHAR NOT NULL,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


CREATE TABLE IF NOT EXISTS standard_equipment_items (
  id                              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  legacy_equipment_id             INTEGER NOT NULL,
  protheus_code                   VARCHAR NOT NULL,
  processor                       VARCHAR,
  memory                          VARCHAR,
  storage                         VARCHAR,
  graphics_card                   VARCHAR,
  conveyor_belt_load_capacity_kg  VARCHAR,
  tube_power_kv                   VARCHAR,
  certificate                     VARCHAR,
  conveyor_belt_type              VARCHAR,
  motopolia_type                  VARCHAR,
  language                        VARCHAR,
  color                           VARCHAR,
  legacy_general_alert_id         INTEGER DEFAULT 0,
  status                          VARCHAR NOT NULL DEFAULT 'active',
  cost_std                        DECIMAL(10,2) NOT NULL DEFAULT 0,
  created_at                      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at                      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

